#!/usr/bin/env python3
"""Three bounded real-BPF capture jobs for this performance run only."""
import json, os, pwd, subprocess, time
from pathlib import Path
ROOT=Path('/home/jaspersao/dev/91kvstore-performance-fix-20261119')
REPO=Path('/home/jaspersao/dev/91kvstore')
UID=pwd.getpwnam('jaspersao').pw_uid

def identity(pid):
    raw=Path(f'/proc/{pid}/stat').read_text().split(') ',1)[1].split()
    return raw[19]

def write(path,value):
    temporary=path.with_suffix('.tmp')
    temporary.write_text(json.dumps(value,indent=2))
    os.chmod(temporary,0o644)
    temporary.replace(path)

def main():
    if os.geteuid()!=0: raise SystemExit('Run with sudo to load real BPF')
    write(ROOT/'capture-helper-ready.json',dict(pid=os.getpid(),ticks=identity(os.getpid())))
    for number in range(1,4):
        if (ROOT/'performance-timed-groups-finished').exists(): return
        request=ROOT/f'capture-request-{number}.json'
        deadline=time.monotonic()+21600
        print(f'Waiting for measured eBPF round {number}/3',flush=True)
        while not request.exists():
            if (ROOT/'performance-timed-groups-finished').exists(): return
            if time.monotonic()>deadline: raise TimeoutError(str(request))
            time.sleep(1)
        job=json.loads(request.read_text()); pid=int(job['pid'])
        proc=Path(f'/proc/{pid}')
        if proc.stat().st_uid!=UID or (proc/'exe').resolve()!=(REPO/'bin/kvstore').resolve() or identity(pid)!=job['ticks']:
            raise RuntimeError('Primary identity mismatch')
        sock=Path(f'/tmp/91kv-perf-{pid}-capture.sock')
        if sock.exists(): raise RuntimeError('Capture socket already exists')
        log_path=ROOT/f'capture-round-{number}.log'
        child=None
        try:
            with log_path.open('wb') as log:
                child=subprocess.Popen([str(REPO/'bin/kvstore-ebpf-capture'),str(pid),str(REPO/'build/ebpf_capture.bpf.o'),'--socket',str(sock)],stdout=log,stderr=log)
            write(ROOT/f'capture-job-{number}.json',dict(pid=child.pid,ticks=identity(child.pid),socket=str(sock)))
            deadline=time.monotonic()+1200
            while not (ROOT/f'capture-stop-{number}').exists():
                if (ROOT/'performance-timed-groups-finished').exists(): break
                if child.poll() is not None: raise RuntimeError(f'capture exited: {log_path}')
                if not proc.exists() or identity(pid)!=job['ticks']: break
                if time.monotonic()>deadline: raise TimeoutError('capture round exceeded 20 minutes')
                time.sleep(.1)
        finally:
            if child is not None and child.poll() is None:
                child.terminate()
                try: child.wait(timeout=10)
                except subprocess.TimeoutExpired: child.kill(); child.wait()
        write(ROOT/f'capture-stopped-{number}.json',dict(exit=child.returncode,socket_removed=not sock.exists()))
        print(f'Capture round {number} stopped; log {log_path}',flush=True)
    print('Three eBPF capture rounds completed.',flush=True)
if __name__=='__main__': main()

