#!/usr/bin/env python3
"""Mac orchestration: benchmarks execute on 135, Replica on isolated 136 copy."""
import json, shlex, subprocess, time, sys
from pathlib import Path
ROOT=Path(__file__).resolve().parent
REMOTE='/home/jaspersao/dev/91kvstore-performance-fix-20261119'
REPO='/home/jaspersao/dev/91kvstore'
COPY='/home/jaspersao/dev/91kvstore-performance-0e25dd7'
OUTPUT=ROOT/'replication'

def ssh(host,args,timeout=700):
    p=subprocess.run(['ssh','-o','BatchMode=yes','jaspersao@172.16.145.'+str(host),shlex.join(args)],capture_output=True,text=True,timeout=timeout)
    if p.returncode: raise RuntimeError(p.stderr+'\n'+p.stdout)
    return p.stdout

def py(host,code): return json.loads(ssh(host,['python3','-c',code]))
def rpc(host,action,args):
    env=['env','KVS_PERF_REPO='+(REPO if host==135 else COPY)]
    return json.loads(ssh(host,env+['python3','-B',REMOTE+'/remote_replication_job.py',action,json.dumps(args)]))
def wait(predicate,message,timeout=60):
    deadline=time.monotonic()+timeout
    while time.monotonic()<deadline:
        result=predicate()
        if result: return result
        time.sleep(.1)
    raise TimeoutError(message)
def alive_online(args):
    s=rpc(136,'status',args)
    if not s['alive']: raise RuntimeError(s['log'])
    return 'replication: enter ONLINE' in s['log']
def read135(name):
    return py(135,f'import pathlib,json; p=pathlib.Path({REMOTE!r})/{name!r}; print(p.read_text() if p.exists() else "null")')
def touch135(name):
    ssh(135,['python3','-c',f'from pathlib import Path; (Path({REMOTE!r})/{name!r}).touch()'])

