#!/usr/bin/env python3
"""Temporarily freeze guest automatic wall-clock corrections; always restore."""
import json,os,signal,subprocess,sys,time
from pathlib import Path
import run_capture_helper
ROOT=Path('/home/jaspersao/dev/91kvstore-performance-fix-20261119')

def run(argv): return subprocess.check_output(argv,text=True,stderr=subprocess.STDOUT).strip()
def write(value):
 with (ROOT/'clock-freeze-events.jsonl').open('a') as history: history.write(json.dumps(value)+'\n')
 p=ROOT/'clock-freeze-ready.json';t=p.with_suffix('.tmp');t.write_text(json.dumps(value,indent=2));os.chmod(t,0o644);t.replace(p)
def terminate(signum,frame):
 raise SystemExit(128+signum)
def main():
 if os.geteuid()!=0: raise SystemExit('Run via sudo')
 if (ROOT/'performance-timed-groups-finished').exists(): raise SystemExit('This run is already marked finished')
 old=ROOT/'capture-helper-ready.json'
 if old.exists():
  owner=json.loads(old.read_text());p=Path(f'/proc/{owner["pid"]}/stat')
  if p.exists() and p.read_text().split(') ',1)[1].split()[19]==owner['ticks']:
   raise SystemExit('First press Ctrl+C in the old waiting capture-helper terminal, then start this helper.')
 vmware=run(['vmware-toolbox-cmd','timesync','status'])
 state=subprocess.run(['systemctl','is-active','systemd-timesyncd'],capture_output=True,text=True)
 ntp_active=state.returncode==0
 meta=dict(pid=os.getpid(),ticks=run_capture_helper.identity(os.getpid()),
  original_vmware_timesync=vmware,original_timesyncd_active=ntp_active,active=False,lifetime='whole_matrix',
  started_realtime=time.time(),started_monotonic=time.monotonic())
 (ROOT/'clock-freeze-original.json').write_text(json.dumps(meta,indent=2))
 errors=[]
 for signum in (signal.SIGTERM,signal.SIGHUP): signal.signal(signum,terminate)
 try:
  subprocess.run(['vmware-toolbox-cmd','timesync','disable'],check=True)
  if ntp_active: subprocess.run(['systemctl','stop','systemd-timesyncd'],check=True)
  meta['active']=True;write(meta)
  print('Clock corrections temporarily paused; original settings will be restored on exit.',flush=True)
  run_capture_helper.main()
  print('Capture rounds complete; waiting for the full performance run to finish before restoring clocks.',flush=True)
  deadline=time.monotonic()+21600
  while not (ROOT/'performance-timed-groups-finished').exists():
   if time.monotonic()>deadline: raise TimeoutError('Performance completion marker not received')
   time.sleep(1)
 finally:
  if ntp_active:
   r=subprocess.run(['systemctl','start','systemd-timesyncd'],capture_output=True,text=True)
   if r.returncode: errors.append(r.stderr)
  r=subprocess.run(['vmware-toolbox-cmd','timesync','enable' if vmware=='Enabled' else 'disable'],capture_output=True,text=True)
  if r.returncode: errors.append(r.stderr)
  meta.update(active=False,restoration_errors=errors,finished_realtime=time.time(),finished_monotonic=time.monotonic());write(meta)
  (ROOT/'clock-freeze-restored.json').write_text(json.dumps(meta,indent=2))
  print('Original clock settings restored.' if not errors else 'Clock restoration errors: '+repr(errors),flush=True)
  if errors: raise RuntimeError(errors)
if __name__=='__main__':main()

