#!/usr/bin/env python3
"""Complete the original matrix, recording failed replication trials honestly."""
import json,time
from pathlib import Path
import run_replication_matrix as base
ROOT=Path(__file__).resolve().parent
OUT=ROOT/'replication'
REMOTE=base.REMOTE

def remote_json(name): return base.read135(name)
def failure_case(case,mode,number,error):
    row=dict(mode=mode,round=number,success=False,error=str(error))
    code=f'import pathlib,json; p=pathlib.Path({REMOTE!r},"replication",{case!r},"measure.json"); print(p.read_text() if p.exists() else "null")'
    row['primary_ack_only']=base.py(135,code)
    if mode=='ebpf':
        row['capture_log']=base.ssh(135,['cat',REMOTE+f'/capture-round-{number}.log'])
    return row

def run_case(number,mode):
    case=f'round-{number}-{mode}'
    pports=base.rpc(135,'ports',dict(case=case,host='172.16.145.135'))
    rports=base.rpc(136,'ports',dict(case=case,host='172.16.145.136'))
    p=dict(case=case,role='primary',host='172.16.145.135',port=pports[0],rdma_port=pports[1],mode=mode,repo=base.REPO)
    r=dict(case=case,role='replica',host='172.16.145.136',port=rports[0],primary_host=p['host'],primary_port=p['port'],repo=base.COPY)
    owner=replica=capture=None
    row=None;cleanup_errors=[]
    print('START',case,flush=True)
    try:
        owner=base.rpc(135,'start',p)
        if mode=='ebpf':
            request=REMOTE+f'/capture-request-{number}.json'
            base.ssh(135,['python3','-c',f'from pathlib import Path; Path({request!r}).write_text({json.dumps(dict(pid=owner["pid"],ticks=owner["ticks"]))!r})'])
            capture=base.wait(lambda: remote_json(f'capture-job-{number}.json'),'real capture helper',120)
            base.wait(lambda: base.py(135,f'import json,pathlib; print(json.dumps(pathlib.Path({capture["socket"]!r}).exists()))'),'capture ready',15)
        command=dict(p,fields=['HSET','k'*32,'v'*128])
        base.wait(lambda: base.rpc(135,'command',command)['value']=='OK','Primary command readiness')
        if mode!='none':
            replica=base.rpc(136,'start',r)
            base.wait(lambda: base.alive_online(r),'Replica ONLINE',90)
        base.rpc(135,'benchmark',dict(p,requests=10000,name='warmup',capture_pid=capture['pid'] if capture else None))
        before=base.rpc(136,'status',r)['cpu_seconds'] if replica else 0
        row=base.rpc(135,'benchmark',dict(p,requests=100000,name='measure',capture_pid=capture['pid'] if capture else None))
        after=base.rpc(136,'status',r)['cpu_seconds'] if replica else 0
        row.update(mode=mode,round=number,replica_cpu_seconds=after-before,replica_cpu_percent=100*(after-before)/row['wall_seconds'],capture_cpu_percent=100*row['capture_cpu_seconds']/row['wall_seconds'])
        if replica:
            row['visibility']=base.rpc(135,'visibility',dict(p,replica_host=r['host'],replica_port=r['port']))
            if not base.alive_online(r): raise RuntimeError('Replica lost ONLINE')
            last=base.rpc(136,'command',dict(r,fields=['HGET','k'*32]))
            if last['value']!=('visibility_00000999_'+'x'*128)[:128]: raise RuntimeError('Replica tail differs')
        row['success']=True
    except Exception as error:
        row=failure_case(case,mode,number,error)
    finally:
        if replica:
            try:
                result=base.rpc(136,'stop',r);(OUT/(case+'-replica.log')).write_text(result['log'])
            except Exception as error: cleanup_errors.append(str(error))
        if capture:
            try:
                base.touch135(f'capture-stop-{number}')
                stopped=base.wait(lambda: remote_json(f'capture-stopped-{number}.json'),'capture cleanup',15)
                if stopped['exit']!=0 or not stopped['socket_removed']: raise RuntimeError(str(stopped))
            except Exception as error: cleanup_errors.append(str(error))
        if owner:
            try:
                result=base.rpc(135,'stop',p);(OUT/(case+'-primary.log')).write_text(result['log'])
            except Exception as error: cleanup_errors.append(str(error))
    if capture:
        import re
        capture_log=base.ssh(135,['cat',REMOTE+f'/capture-round-{number}.log'])
        (OUT/(case+'-capture.log')).write_text(capture_log)
        counts=re.findall(r'failure_count oversize=(\d+) ring_full=(\d+) read_error=(\d+)',capture_log)
        row['kernel_failures']=dict(zip(('oversize','ring_full','read_error'),map(int,counts[-1]))) if counts else None
        if not counts or any(int(value) for count in counts for value in count):
            row['success']=False
            row['error']='Nonzero or unavailable kernel failure counters'
    row['cleanup_errors']=cleanup_errors
    if cleanup_errors: row['success']=False
    (OUT/(case+'.json')).write_text(json.dumps(row,indent=2))
    print('PASS' if row['success'] else 'FAIL',case,flush=True)
    return row

def main():
    OUT.mkdir(exist_ok=True)
    rows=[]
    for number in range(1,4):
        modes=['none','socket','ebpf']
        for mode in modes[number-1:]+modes[:number-1]:
            rows.append(run_case(number,mode))
    result=dict(completed=len(rows)==9,passed=all(r['success'] for r in rows),results=rows,
                successful=sum(r['success'] for r in rows),failed=sum(not r['success'] for r in rows))
    (OUT/'summary.json').write_text(json.dumps(result,indent=2))
    print('COMPLETED',json.dumps({k:v for k,v in result.items() if k!='results'}),flush=True)
if __name__=='__main__': main()
